const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
function screen(id){['setup','view','battle'].forEach(x=>$('#'+x).hidden=x!==id);$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.screen===id));window.scrollTo(0,0)}
$$('nav button').forEach(b=>b.onclick=()=>screen(b.dataset.screen));$('#openView').onclick=()=>screen('view');$('#choose').onclick=()=>screen('setup');$('#start').onclick=()=>screen('battle');$('#back').onclick=()=>screen('setup');
$$('[data-arena]').forEach(b=>b.onclick=()=>{$$('[data-arena]').forEach(x=>x.classList.toggle('selected',x===b));$('#arenaImage').src='../../assets/arena-'+b.dataset.arena+'.png';$('#arenaName').textContent={yard:'Офисный двор',meeting:'Переговорная',kitchen:'Кухня'}[b.dataset.arena]});
$$('#rounds button').forEach(b=>b.onclick=()=>{$$('#rounds button').forEach(x=>x.classList.toggle('selected',x===b))});
$$('[data-fighter]').forEach(b=>b.onclick=()=>{$$('[data-fighter]').forEach(x=>x.classList.toggle('selected',x===b));const rose=b.dataset.fighter==='rose';$('#name').textContent=$('#viewName').textContent=rose?'Розовая пантера':'Островной боец';$('#setupModel').src=$('#detailModel').src=rose?'../../art/source/rose-hands-v1/candidate.glb':'island.glb'});
$('#resetCamera').onclick=()=>{$('#detailModel').cameraOrbit='20deg 80deg 105%';$('#detailModel').fieldOfView='30deg'};
$$('[data-pose]').forEach(b=>b.onclick=()=>{$$('[data-pose]').forEach(x=>x.classList.toggle('selected',x===b));$('#detailModel').classList.toggle('dancing',b.dataset.pose==='dance');$('#movePreview').hidden=b.dataset.pose!=='jab';$('#detailModel').autoRotate=b.dataset.pose==='dance'});
$$('[data-move]').forEach(b=>b.onclick=()=>{$('#poseImage').src='../../art/previews/rose-motion/'+b.dataset.move+'.png';$$('[data-move]').forEach(x=>x.classList.toggle('selected',x===b))});
$('#pause').onclick=()=>$('.pause-overlay').hidden=false;$('#resume').onclick=()=>$('.pause-overlay').hidden=true;$('#exit').onclick=()=>{$('.pause-overlay').hidden=true;screen('setup')};
const stick=$('#stick'), knob=$('#knob');function move(e){const r=stick.getBoundingClientRect(),max=r.width*.28;let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,d=Math.hypot(x,y);if(d>max){x*=max/d;y*=max/d}knob.style.transform=`translate(${x}px,${y}px)`;$('#fightNote').textContent=Math.abs(x)>Math.abs(y)?(x>0?'Вперёд':'Назад'):(y>0?'Шаг в ближнюю сторону':'Шаг в дальнюю сторону')}
stick.onpointerdown=e=>{stick.setPointerCapture(e.pointerId);move(e)};stick.onpointermove=e=>{if(stick.hasPointerCapture(e.pointerId))move(e)};stick.onpointerup=stick.onpointercancel=()=>{knob.style.transform='';$('#fightNote').textContent='Джойстик: вперёд, назад и шаги в стороны'};
$$('[data-hit]').forEach(b=>{b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);b.classList.add('pressed');$('#fightNote').textContent=b.dataset.hit==='БЛОК'?'Защита — удерживай кнопку':'Приём: '+b.dataset.hit};b.onpointerup=b.onpointercancel=()=>b.classList.remove('pressed')});
